def main(mod_dir):
    doc = {"format": "dingdong-lore-codex-v1", "chapters": CHAPTERS, "entries": E}
    path = Path(mod_dir, "Quests", "Lore", "codex.json")
    # CRLF, like Quests/ResidentStories.json and the other lore files.
    path.write_bytes((json.dumps(doc, ensure_ascii=False, indent=1) + "\n").replace("\n", "\r\n").encode("utf-8"))
    print(f"wrote {path} entries={len(E)}")


if __name__ == "__main__":
    main(sys.argv[1])
